    keywords: ["πληρότητα", "icecat", "internet", "κατασκευαστής", "φωτογραφίες από το internet", "δημοσίευση", "ημιτελή", "κρυφά", "φωτογραφία", "διαστάσεις", "βάρος", "χαρακτηριστικά"],
